    Prendre: "Nhận",
    "La Ligue revient plus forte, palier par palier : le Conseil 4 puis le Maître au Nv. 100 avec un rang (Élite I à V), sans les dresseurs des salles, un Centre Pokémon avant chacun. Une défaite renvoie au premier. Chaque palier battu donne une gemme légendaire, d'un type à choisir parmi ceux de la Ligue, et le cadre de la Ligue en III et en V.":
      "Liên đoàn trở lại mạnh hơn qua từng mốc: Tứ Thiên Vương rồi Nhà vô địch ở Cấp 100 kèm hạng (Tinh anh I đến V), không có huấn luyện viên trong các phòng, trước mỗi trận đều có một Trung tâm Pokémon. Thua một trận là quay lại từ đầu. Mỗi mốc vượt qua tặng một ngọc huyền thoại, hệ do bạn chọn trong các hệ của Liên đoàn, và khung Liên đoàn ở mốc III và V.",
