    "Super Bonbons du jour": "Kẹo hiếm hôm nay",
    "Les {n} Super Bonbons du jour sont gagnés : leurs paliers doublent les Bonbons Exp. à la place.": "Hôm nay đã thắng {n} Kẹo hiếm: các mốc đó thay vào đó sẽ nhân đôi Kẹo EXP.",
