    Gains: "Tiền thắng",
    Multiplicateur: "Hệ số nhân",
    "Trois symboles identiques sur une ligne jouée rapportent des jetons, deux Baies Framby ou deux Kokiyas au début d'une ligne aussi. Les 5 lignes sont jouées à chaque partie.":
      "Ba biểu tượng trùng nhau trên một dòng đã chơi sẽ trả xu; hai quả Razz Berry hoặc hai Shellder ở đầu dòng cũng vậy. Mỗi lượt quay đều tính cả 5 dòng.",
    "Parties automatiques": "Tự động quay",
    ARGENT: "TIỀN",
    "Billes par lancer": "Bóng mỗi lần bắn",
    "Chaque bille finit dans une case : des Pokédollars sur les côtés, rien sur les deux suivantes, un Super Bonbon au milieu. Le trou du milieu garde parfois une bille : un objet au hasard, chances ci-dessous (les Bonbons Exp. grossissent avec les badges de la région). Les deux cibles donnent leur objet au bout d'un nombre de touches.":
      "Mỗi quả bóng rơi vào một ô: hai bên là Pokédollars, hai ô kế tiếp không có gì, ô giữa là Kẹo hiếm. Lỗ ở giữa đôi khi giữ bóng lại: một vật phẩm ngẫu nhiên, tỉ lệ ở bên dưới (Kẹo EXP tăng theo số huy hiệu của vùng). Hai mục tiêu sẽ trao vật phẩm sau một số lần trúng.",
    "Casino de Lavandia": "Sòng bạc Mauville",
    "Casino de Voilaroc": "Sòng bạc Veilstone",
    "Prochain Casino": "Sòng bạc tiếp theo",
    "Une autre région": "Vùng khác",
    "Joue à {r} pour l'ouvrir": "Chơi ở {r} để mở khóa",
    Commun: "Thường",
    "Peu commun": "Ít gặp",
    "Très rare": "Rất hiếm",
    "{n} jetons avant {mon} ✨": "Còn {n} xu là tới {mon} ✨",
    "Chaque jour, un boss chromatique par région, à affronter avec 2 alliés. Essais illimités : à chaque K.O., 1 % de chance de le capturer.":
      "Mỗi ngày có một boss dạng sáng ở mỗi vùng, đánh cùng 2 đồng đội. Thử không giới hạn: mỗi lần hạ gục có 1% cơ hội bắt được.",
    "{lv} ramené au niveau max": "{lv} được giới hạn ở cấp tối đa",
    "Les espèces des 50 équipes les plus rapides contre ce boss. Sous chacune, ton meilleur exemplaire : un clic l'ajoute à ton équipe.":
      "Các loài trong 50 đội đánh boss này nhanh nhất. Dưới mỗi loài là bản tốt nhất của bạn: chạm để thêm vào đội.",
    "Les espèces des équipes qui ont capturé ce légendaire. Sous chacune, ton meilleur exemplaire : un clic l'ajoute à ton équipe.":
      "Các loài trong những đội đã bắt được Pokémon huyền thoại này. Dưới mỗi loài là bản tốt nhất của bạn: chạm để thêm vào đội.",
    Efficaces: "Mạnh",
