    "Glisse un Pokémon du PC vers un emplacement (échange s'il est pris), un membre vers le PC pour le retirer, ou entre deux membres pour changer l'ordre d'envoi. Un clic ajoute / retire.":
      "Kéo Pokémon từ PC vào một ô (nếu ô đã có sẽ đổi chỗ), kéo thành viên vào PC để gỡ ra, hoặc kéo giữa hai thành viên để đổi thứ tự ra trận. Chạm để thêm / gỡ.",
    "Niveau moyen <b>{n}</b>": "Cấp trung bình <b>{n}</b>",
    "Ton équipe d'event est complète : glisse-le sur un membre pour l'échanger.": "Đội sự kiện của bạn đã đầy: kéo nó lên một thành viên để đổi chỗ.",
