    Défaites: "Thua",
    "Le jeu est et restera <b>gratuit</b>, sans pub et sans rien à acheter pour avancer. Mais le faire tourner en ligne a un coût bien réel :":
      "Game vẫn luôn <b>miễn phí</b>, không quảng cáo và không cần mua gì để tiến xa hơn. Nhưng để game chạy online thì có chi phí thật:",
    "Nouveaux au Pokédex": "Mới trong Pokédex",
    "Objets trouvés": "Vật phẩm tìm thấy",
    "Salut ! Poke'Catch est fait par <b>un petit dev solo</b>, sur son temps libre, par pur plaisir de fan.":
      "Chào bạn! Poke'Catch do <b>một dev solo</b> làm trong thời gian rảnh, hoàn toàn vì đam mê fan.",
    "Si le jeu te plaît et que tu peux donner un petit coup de pouce, ça m'aide à garder tout ça en ligne et à continuer d'ajouter du contenu. Et si tu ne peux pas : jouer, en parler à tes potes et remonter les bugs sur le Discord, c'est déjà énorme. Merci ❤️":
      "Nếu bạn thích game và có thể ủng hộ một chút thì sẽ giúp mình duy trì mọi thứ online và tiếp tục thêm nội dung. Còn nếu không thì: chơi game, rủ bạn bè và báo lỗi trên Discord đã là rất nhiều rồi. Cảm ơn bạn ❤️",
