    "Le papi de la Pension te confie un œuf mystère : il part couver à la Pension !": "Ông lão ở Nhà trẻ Pokémon giao cho bạn một quả trứng bí ẩn: nó sẽ được đem ấp ở Nhà trẻ Pokémon!",
