    "Tu n'es pas seul": "Bạn không đơn độc",
    "D'autres dresseurs jouent en même temps : suis leurs exploits dans le chat et compare tes temps aux leurs dans les classements.":
      "Các huấn luyện viên khác cũng đang chơi cùng lúc: xem thành tích của họ trong chat và so thời gian của bạn với họ trên bảng xếp hạng.",
    "Les events légendaires": "Sự kiện huyền thoại",
    "Un légendaire apparaît pour une heure, pour tout le monde : sois le premier à le capturer, avec l'équipe qui le contre.":
      "Một Pokémon huyền thoại xuất hiện trong một giờ cho tất cả mọi người: hãy là người đầu tiên bắt được nó, với đội hình khắc chế nó.",
    "Bonjour ! Bienvenue dans le monde des <b>Pokémon</b> ! Je m'appelle <b>Chen</b>, mais on m'appelle le Prof. Pokémon.":
      "Xin chào! Chào mừng đến với thế giới <b>Pokémon</b>! Tôi là <b>Oak</b>, nhưng mọi người vẫn gọi tôi là Giáo sư Pokémon.",
    "Ici, ton aventure avance toute seule : ton équipe combat et capture les Pokémon sauvages… <b>même quand tu n'es pas là</b> !":
      "Ở đây, cuộc phiêu lưu của bạn tự diễn ra: đội của bạn chiến đấu và bắt Pokémon hoang dã… <b>ngay cả khi bạn vắng mặt</b>!",
    "Bats les <b>Champions d'Arène</b> pour gagner leurs badges et ouvrir de nouvelles routes.": "Đánh bại các <b>nhà vô địch đấu trường</b> để giành huy hiệu và mở tuyến đường mới.",
    "Et ouvre l'œil : des <b>Pokémon légendaires</b> apparaissent lors d'events limités dans le temps.": "Và để mắt nhé: <b>Pokémon huyền thoại</b> xuất hiện trong các sự kiện giới hạn thời gian.",
    "Mais d'abord, il te faut un partenaire. Viens, <b>choisis ton premier Pokémon</b> !": "Nhưng trước hết, bạn cần một người bạn đồng hành. Nào, <b>chọn Pokémon đầu tiên của bạn</b>!",
