    "Pas tous au PC": "Không phải tất cả đều ở PC",
    "Un de chaque espèce : les doublons se changent en XP pour la famille, sauf ceux que « Garder les doublons » garde. Les chromatiques comptent à part et gardent toujours un doublon de la forme de base.":
      "Mỗi loài một con: bản sao chuyển thành EXP cho họ tiến hoá, trừ những con được “Giữ bản sao” giữ lại. Dạng sáng tính riêng và luôn được giữ một bản sao ở dạng gốc.",
    "Désactivé : un doublon se change en XP, sauf s'il peut encore devenir une évolution que tu n'as pas (un Mystherbe pour Rafflesia, un autre pour Joliflor) ; une famille à plusieurs branches garde aussi une forme de base. Activé : un de chaque espèce, plus un doublon de la forme de base.":
      "Tắt: bản sao chuyển thành EXP, trừ khi nó còn có thể tiến hoá thành dạng bạn chưa có (một Oddish cho Vileplume, một con khác cho Bellossom); họ có nhiều nhánh cũng giữ thêm một dạng gốc. Bật: mỗi loài một con, cộng thêm một bản sao ở dạng gốc.",
    "{item} ×{n} dans le Sac de {region} : les deux Sacs se réunissent quand tu bats la Ligue de {to}.": "{item} ×{n} trong Túi {region}: hai Túi sẽ hợp lại khi bạn thắng Liên đoàn {to}.",
    "Bats {name} en Élite {tier}.": "Đánh bại {name} ở Elite {tier}.",
