    "Les murs et les gardiens en donnent. Touche une géode pour la casser : elle révèle la gemme d'un Pokémon, et peut monter d'une rareté pendant que tu la frappes.":
      "Tường và hộ vệ cho chúng. Chạm vào tinh thạch để đập vỡ: nó lộ ra ngọc của một Pokémon, và có thể tăng độ hiếm trong lúc bạn đập.",
