    "Une gemme du Pokémon de ton choix, contre des Éclats.": "Một viên ngọc của Pokémon bạn chọn, đổi bằng Mảnh.",
    "Aucun de tes Pokémon n'a encore de gemme possible.": "Chưa Pokémon nào của bạn có thể nhận ngọc.",
    "+1 gemme {name}": "+1 Ngọc {name}",
    Recycler: "Tái chế",
    "Envoie {n} Pokémon : ils descendent d'étage en étage jusqu'à être K.O. ou rappelés. Un gardien deux fois plus fort tous les 10 étages. Chaque expédition a son thème, affiché sur son encart : tous ses adversaires sont de ses types, choisis des Pokémon efficaces contre eux. {d} à {m} expéditions par jour selon les emplacements achetés, chaque Pokémon une fois par jour ; au retour, l'XP et le butin des étages franchis. La première fois aux étages 100, 150 et 200 : une géode légendaire, une apparence ou un cadre.":
      "Gửi {n} Pokémon: đội đi xuống từng tầng cho tới khi ngất hoặc bị bạn gọi về. Cứ 10 tầng lại có một hộ vệ mạnh gấp đôi. Mỗi chuyến có chủ đề riêng, hiện trên ô của nó: mọi đối thủ đều thuộc hệ đó, nên hãy chọn Pokémon khắc chế chúng. Mỗi ngày {d} đến {m} chuyến tuỳ số ô đã mua, mỗi Pokémon đi một lần một ngày; khi về, bạn nhận XP và chiến lợi phẩm của các tầng đã qua. Lần đầu lên tới tầng 100, 150 và 200: một tinh thạch huyền thoại, một ngoại hình hoặc một khung.",
    "Prochain palier : étage {n}": "Mốc tiếp theo: tầng {n}",
    "Record : {html}": "Kỷ lục: {html}",
    "Apparence : {name}": "Ngoại hình: {name}",
    "Cadre : {name}": "Khung: {name}",
