    "Échanger des Éclats": "Đổi Mảnh",
    "Une gemme du Pokémon de ton choix, contre des Éclats. Les murs et les gardiens en donnent ; une gemme recyclée aussi.":
      "Một viên ngọc của Pokémon bạn chọn, đổi bằng Mảnh. Tường và hộ vệ cũng cho Mảnh; ngọc tái chế cũng vậy.",
    "Les étages sautés ne donnent ni butin ni XP.": "Tầng bỏ qua không cho chiến lợi phẩm lẫn XP.",
    "Étage de départ": "Tầng xuất phát",
    "Départ : étage {n}": "Xuất phát: tầng {n}",
    "Atteins d'abord l'étage {n}.": "Hãy lên tới tầng {n} trước.",
    "{n} gemmes de tes Pokémon, contre des Éclats. La sélection change toutes les {h} h ; tu peux la changer avant contre des ₽. Les murs et les gardiens donnent des Éclats ; une gemme recyclée aussi.":
      "{n} viên ngọc của Pokémon bạn, đổi bằng Mảnh. Danh sách đổi mới sau mỗi {h} giờ; có thể đổi sớm bằng ₽. Tường và hộ vệ cho Mảnh; ngọc tái chế cũng vậy.",
    "Nouvelle sélection dans {t}": "Danh sách mới sau {t}",
